ga2m(){return"\u0644\u06cc\u0633\u062a\u06a9\u0631\u0627\u0648\u06d5 \u0628\u06c6 \u067e\u06d5\u06cc\u0648\u06d5\u0646\u062f\u06cc\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u0627\u0646"},
ga2n(){return"\u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u0648\u0698\u0627\u0648\u06d5\u062a\u06d5\u0648\u06d5\u060c \u0626\u06d5\u0645 \u062a\u0627\u0642\u06cc\u06af\u06d5\u06cc\u06d5 \u062f\u06d5\u0631\u0646\u0627\u06a9\u06d5\u0648\u06ce\u062a \u06a9\u0627\u062a\u06ce\u06a9 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06ce\u06a9 \u0628\u06d5\u062f\u0648\u0627\u06cc \u062a\u0627\u0642\u06cc\u06af\u06d5\u06cc\u06d5\u06a9\u062f\u0627 \u062f\u06d5\u06af\u06d5\u0695\u06ce\u062a \u0628\u06c6 \u067e\u06d5\u06cc\u0648\u06d5\u0633\u062a\u0628\u0648\u0648\u0646\u060c \u0648\u06d5 \u0647\u06cc\u0686 \u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u062e\u06c6\u06a9\u0627\u0631\u0627\u0646\u06d5\u06cc \u0646\u0648\u06ce\u06cc \u062f\u06a9\u062a\u06c6\u0631/\u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0648\u06d5\u0631\u0646\u0627\u06af\u0631\u06ce\u062a."},
