gaix(){return"\u06af\u06d5\u0695\u0627\u0646\u06d5\u0648\u06d5 \u0628\u06c6 \u0628\u0646\u06d5\u0695\u06d5\u062a\u06cc"},
gajD(){return"\u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u062f\u0646\u06cc \u0695\u06ce\u0698\u06d5\u06cc \u06a9\u06c6\u0645\u06cc\u0633\u06cc\u06c6\u0646 \u0628\u06c6 \u0647\u06d5\u0631 \u0645\u0627\u062f\u06d5\u06cc\u06d5\u06a9"},
gajn(){return"\u0695\u06ce\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
ajg(a){return"\u0695\u06ce\u0633\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u2014 "+a},
gaji(){return"\u0648\u0634\u06d5\u06cc\u06d5\u06a9\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce \u0628\u06c6 \u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u0626\u06d5\u0645 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u062f\u0627\u062f\u06d5\u0646\u06ce\u062a\u060c \u062f\u06d5\u0633\u062a\u0628\u06d5\u062c\u06ce. \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc\u06d5\u06a9\u06d5 \u0695\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0644\u06d5\u06af\u06d5\u06b5 \u0626\u06d5\u0648 \u06a9\u0627\u0631\u0645\u06d5\u0646\u062f\u06d5 \u0647\u0627\u0648\u0628\u06d5\u0634 \u0628\u06a9\u06d5 \u2014 \u0647\u06cc\u0686 \u0626\u06cc\u0645\u06d5\u06cc\u0644\u06ce\u06a9 \u0646\u0627\u0646\u06ce\u0631\u062f\u0631\u06ce\u062a."},
gajk(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce"},
gajf(){return"\u062f\u0648\u0648\u067e\u0627\u062a\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc"},
gajj(){return"\u0648\u0634\u06d5 \u0646\u0647\u06ce\u0646\u06cc\u06cc\u06d5\u06a9\u0627\u0646 \u0648\u06d5\u06a9 \u06cc\u06d5\u06a9 \u0646\u06cc\u0646"},
gajm(){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u062f\u06d5\u0628\u06ce\u062a \u0644\u0627\u0646\u06cc\u06a9\u06d5\u0645 \u0666 \u067e\u06cc\u062a \u0628\u06ce\u062a"},
ajl(a){return"\u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u06af\u06c6\u0695\u062f\u0631\u0627. \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0646\u0648\u06ce \u0695\u0627\u0633\u062a\u06d5\u0648\u062e\u06c6 \u0644\u06d5\u06af\u06d5\u06b5 "+a+" \u0647\u0627\u0648\u0628\u06d5\u0634 \u0628\u06a9\u06d5."},
ajh(a){return"\u06af\u06c6\u0695\u06cc\u0646\u06cc \u0648\u0634\u06d5\u06cc \u0646\u0647\u06ce\u0646\u06cc \u0633\u06d5\u0631\u06a9\u06d5\u0648\u062a\u0648\u0648 \u0646\u06d5\u0628\u0648\u0648: "+a},
